private static char[] transcodeRemaining(final Char prev, final Char curr, final Char next, final Char aNext) {
    // 1. EV -> AF
    if (curr == 'E' && next == 'V') {
        return CHARS_AF;
    }

    // A, E, I, O, U -> A
    if (isVowel(curr)) {
        return CHARS_A;
    }

    // 2. Q -> G, Z -> S, M -> N
    if (curr == 'Q') {
        return CHARS_G;
    } else if (curr == 'Z') {
        return CHARS_S;
    } else if (curr == 'M') {
        return CHARS_N;
    }

    // 3. KN -> NN else K -> C
    if (curr == 'K') {
        if (next == 'N') {
            return CHARS_NN;
        }
        return CHARS_C;
    }

    // 4. SCH -> SSS
    if (curr == 'S' && next == 'C' && aNext == 'H') {
        return CHARS_SSS;
    }

    // PH -> FF
    if (curr == 'P' && next == 'H') {
        return CHARS_FF;
    }

    // 5. H -> If previous or next is a non vowel, previous.
    if (curr == 'H' && (!isVowel(prev) || !isVowel(next))) {
        return new char[] { prev };
    }

    // 6. W -> If previous is vowel, previous.
    if (curr == 'W' && isVowel(prev)) {
        return new char[] { prev };
    }

    return new char[] { curr };
}

